/* ============ P14 Rompecabezas (tocar y cambiar) ============ */
const SIZE = 3;
const TILE_PCT = 100/3;
const TOTAL = SIZE*SIZE;
let board = Array.from({length:TOTAL}, (_,i)=> i+1);   // [1..9]
const boardEl = document.getElementById('board');
const statusEl = document.getElementById('status');
const STATUS_TXT = 'tocá dos piezas para cambiarlas';
let tileEls = {};
let selected = null;   // valor de la pieza seleccionada
let locked = false;

function buildTiles(){
  boardEl.innerHTML = '';
  tileEls = {};
  for(let val=1; val<=TOTAL; val++){
    const tile = document.createElement('div');
    tile.className = 'tile';
    const row = Math.floor((val-1)/SIZE), col = (val-1)%SIZE;
    tile.style.backgroundPosition = `${col*50}% ${row*50}%`;
    tile.addEventListener('click', ()=>selectTile(val));
    boardEl.appendChild(tile);
    tileEls[val] = tile;
  }
  positionTiles();
}
function positionTiles(){
  board.forEach((val, idx)=>{
    const row = Math.floor(idx/SIZE), col = idx%SIZE;
    const tile = tileEls[val];
    tile.style.left = (col*TILE_PCT) + '%';
    tile.style.top = (row*TILE_PCT) + '%';
  });
}
function clearSelection(){
  if(selected !== null){ tileEls[selected].classList.remove('selected'); }
  selected = null;
}
function selectTile(val){
  if(locked) return;
  if(selected === null){
    selected = val;
    tileEls[val].classList.add('selected');
    return;
  }
  if(selected === val){ clearSelection(); return; }   // tocar la misma = deseleccionar
  const a = board.indexOf(selected), b = board.indexOf(val);
  [board[a], board[b]] = [board[b], board[a]];
  clearSelection();
  positionTiles();
  setTimeout(checkWin, 300);
}
function checkWin(){
  const solved = board.every((v,i)=> v === i+1);
  if(solved){
    locked = true;
    statusEl.textContent = '¡lo armaste! 🧡';
    statusEl.classList.add('win');
    Object.values(tileEls).forEach(t=> t.classList.add('win-glow'));
    document.getElementById('nextBtn14').style.display = 'inline-block';
  }
}
function shuffleBoard(){
  let arr;
  do{
    arr = Array.from({length:TOTAL}, (_,i)=> i+1);
    for(let i=arr.length-1;i>0;i--){
      const j = Math.floor(Math.random()*(i+1));
      [arr[i],arr[j]] = [arr[j],arr[i]];
    }
  } while(arr.every((v,i)=> v === i+1));   // que no quede ya armado
  board = arr;
  locked = false;
  clearSelection();
  statusEl.classList.remove('win');
  statusEl.textContent = STATUS_TXT;
  Object.values(tileEls).forEach(t=> t.classList.remove('win-glow'));
  document.getElementById('nextBtn14').style.display = 'none';
  positionTiles();
}
document.getElementById('shuffleBtn').addEventListener('click', shuffleBoard);
document.getElementById('nextBtn14').addEventListener('click', ()=> showPage('18'));
buildTiles();

/* ============ P15 Sopa de letras ============ */
const wsWordsData = [
  {key:'REGALOS', label:'REGALOS'},
  {key:'UNICO', label:'ÚNICO'},
  {key:'FIESTA', label:'FIESTA'},
  {key:'PASTEL', label:'PASTEL'},
  {key:'CUMPLEANERO', label:'CUMPLEAÑERO'},
  {key:'AMOR', label:'AMOR'},
  {key:'CUMPLEANOS', label:'CUMPLEAÑOS'}
];
const WS_SIZE = 11;
let wsGridData = [];
let wsFound = new Set();
let wsStart = null;

function generateWordSearch(){
  const size = WS_SIZE;
  const grid = Array.from({length:size},()=>Array(size).fill(''));
  const dirs = [[0,1],[1,0],[1,1],[1,-1]];
  wsWordsData.forEach(w=>{
    const word = w.key;
    let placed = false, attempts = 0;
    while(!placed && attempts < 300){
      attempts++;
      const dir = dirs[Math.floor(Math.random()*dirs.length)];
      const reverse = Math.random() < 0.5;
      const letters = reverse ? word.split('').reverse().join('') : word;
      const row0 = Math.floor(Math.random()*size);
      const col0 = Math.floor(Math.random()*size);
      let fits = true;
      for(let i=0;i<letters.length;i++){
        const rr = row0 + dir[0]*i, cc = col0 + dir[1]*i;
        if(rr<0||rr>=size||cc<0||cc>=size){fits=false;break;}
        if(grid[rr][cc] !== '' && grid[rr][cc] !== letters[i]){fits=false;break;}
      }
      if(fits){
        for(let i=0;i<letters.length;i++){
          const rr = row0 + dir[0]*i, cc = col0 + dir[1]*i;
          grid[rr][cc] = letters[i];
        }
        placed = true;
      }
    }
  });
  const alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  for(let r=0;r<size;r++) for(let c=0;c<size;c++) if(!grid[r][c]) grid[r][c] = alpha[Math.floor(Math.random()*alpha.length)];
  return grid;
}

function renderWordSearch(){
  wsGridData = generateWordSearch();
  const gridEl = document.getElementById('wsGrid');
  gridEl.style.gridTemplateColumns = `repeat(${WS_SIZE}, 1fr)`;
  gridEl.innerHTML = '';
  for(let r=0;r<WS_SIZE;r++){
    for(let c=0;c<WS_SIZE;c++){
      const cell = document.createElement('div');
      cell.className = 'ws-cell';
      cell.textContent = wsGridData[r][c];
      cell.dataset.r = r; cell.dataset.c = c;
      cell.addEventListener('click', ()=> onWsCellClick(r,c,cell));
      gridEl.appendChild(cell);
    }
  }
  const wordsEl = document.getElementById('wsWords');
  wordsEl.innerHTML = wsWordsData.map(w=>`<div id="wsw-${w.key}">${w.label}</div>`).join('');
  wsFound = new Set();
  wsStart = null;
}
function cellEl(r,c){ return document.querySelector(`.ws-cell[data-r="${r}"][data-c="${c}"]`); }
function onWsCellClick(r,c,cell){
  if(!wsStart){
    wsStart = {r,c};
    cell.classList.add('sel');
    return;
  }
  const dr = r - wsStart.r, dc = c - wsStart.c;
  const validLine = dr===0 || dc===0 || Math.abs(dr)===Math.abs(dc);
  if(validLine){
    const steps = Math.max(Math.abs(dr), Math.abs(dc));
    const stepR = Math.sign(dr), stepC = Math.sign(dc);
    let letters = '', cells = [];
    for(let i=0;i<=steps;i++){
      const rr = wsStart.r + stepR*i, cc = wsStart.c + stepC*i;
      letters += wsGridData[rr][cc];
      cells.push([rr,cc]);
    }
    const reversed = letters.split('').reverse().join('');
    const match = wsWordsData.find(w => !wsFound.has(w.key) && (w.key === letters || w.key === reversed));
    if(match){
      cells.forEach(([rr,cc])=> cellEl(rr,cc).classList.add('found'));
      wsFound.add(match.key);
      document.getElementById('wsw-'+match.key).classList.add('done');
      if(wsFound.size === wsWordsData.length){
        document.getElementById('wsBackBtn').style.display = 'inline-block';
      }
    }
  }
  cellEl(wsStart.r, wsStart.c).classList.remove('sel');
  wsStart = null;
}
renderWordSearch();

/* ============ P16 Confeti ============ */
const canvas = document.getElementById('confetti');
const ctx = canvas.getContext('2d');
function resize(){ canvas.width = innerWidth; canvas.height = innerHeight; }
resize(); window.addEventListener('resize', resize);
let particles = [];
function launchConfetti(){
  const colors = ['#7a1c2f','#e7acbe','#decfb5','#c9403f'];
  for(let i=0;i<140;i++){
    particles.push({
      x: innerWidth/2 + (Math.random()-0.5)*200, y: innerHeight*0.3,
      vx:(Math.random()-0.5)*8, vy:Math.random()*-8-4, g:0.25,
      size:Math.random()*7+4, color:colors[Math.floor(Math.random()*colors.length)],
      rot:Math.random()*360, vr:(Math.random()-0.5)*12, life:150
    });
  }
}
function loop(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  particles.forEach(p=>{
    p.vy += p.g; p.x += p.vx; p.y += p.vy; p.rot += p.vr; p.life--;
    ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.rot*Math.PI/180);
    ctx.fillStyle = p.color; ctx.fillRect(-p.size/2,-p.size/2,p.size,p.size*0.6);
    ctx.restore();
  });
  particles = particles.filter(p=>p.life>0 && p.y<innerHeight+40);
  requestAnimationFrame(loop);
}
loop();
document.getElementById('confettiBtn').addEventListener('click', launchConfetti);

